use std::collections::HashSet;

fn has_common_element(a: Vec<i32>, b: Vec<i32>) -> bool {
    // To minimize memory usage, build the hash set from the smaller array.
    let (small, large) = if a.len() <= b.len() {
        (a, b)
    } else {
        (b, a)
    };

    let mut seen = HashSet::new();
    // Insert all elements of the smaller array into the set.
    for x in small {
        seen.insert(x);
    }
    // Check whether any element of the larger array is already in the set.
    for y in large {
        if seen.contains(&y) {
            return true;
        }
    }
    false
}

